rows.cmd:
$c = "$env:USERPROFILE\.claude.json"
$j = Get-Content $c -Raw | ConvertFrom-Json
"=== per-project mcpServers (jen jmena) ==="
foreach ($p in $j.projects.PSObject.Properties) {
  $m = $p.Value.mcpServers
  if ($m -and $m.PSObject.Properties.Name.Count -gt 0) { "{0}  ->  {1}" -f $p.Name, (($m.PSObject.Properties.Name) -join ', ') }
}
"=== globalni settings.local.json ==="
$l = "$env:USERPROFILE\.claude\settings.local.json"; if (Test-Path $l) { (Get-Content $l -Raw) -replace '(?i)("[^"]*(key|token|secret)[^"]*"\s*:\s*")[^"]*', '$1<redigovano>' } else { "NEEXISTUJE" }
"=== projektovy settings.local.json (jen klice) ==="
$pl = "W:\dev\gsd\repo\.claude\settings.local.json"; if (Test-Path $pl) { ((Get-Content $pl -Raw | ConvertFrom-Json).PSObject.Properties.Name) -join ', ' } else { "NEEXISTUJE" }
"=== .claude/sinogard-hooks.json v repu? ==="
if (Test-Path "W:\dev\gsd\repo\.claude\sinogard-hooks.json") { "existuje" } else { "NEEXISTUJE" }

$org = 'https://dev.azure.com/wittenberger'; $proj = 'GSD'
$sha = '01ad14d8f7b76d4a5f7c71a91753a7eef4bbdd08'
$runs = az pipelines runs list --organization $org --project $proj --top 20 --query-order QueueTimeDesc --output json | ConvertFrom-Json
$run = $runs | Where-Object { $_.sourceVersion -eq $sha } | Sort-Object id -Descending | Select-Object -First 1
if ($run) { "NALEZEN: $($run.buildNumber)  id=$($run.id)  status=$($run.status)  result=$($run.result)  branch=$($run.sourceBranch)  queue=$($run.queueTime)  finish=$($run.finishTime)" }
else { "ZADNY beh pro $sha ve 20 nejnovejsich"; "--- nejnovejsich 8 ---"; $runs | Select-Object -First 8 buildNumber,id,status,result,sourceBranch,@{n='sha';e={$_.sourceVersion.Substring(0,7)}} | Format-Table -AutoSize }

Add-Type -AssemblyName Microsoft.VisualBasic
$base = "C:\Users\tomas\AppData\Local\Temp\claude\W--dev-gsd-repo\37436679-5e08-4363-8f49-5f176298a0a5\scratchpad"
foreach ($n in @('base-0104','red-0105','red-016','red-017','mutant')) {
  $p = Join-Path $base $n
  [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($p, 'DoNotDeletesomethingWrong')
}

cd W:\dev\gsd\repo
. .\scripts\dev-common.ps1; Import-DevEnvironmentFile; $env:GSD_TEST_PG = Get-PgConnectionString
dotnet build Gsd.slnx -c Release --nologo 2>&1 | Select-String -Pattern 'Build succeeded|error' | Select-Object -First 5
if ($LASTEXITCODE -ne 0) { "BUILD SELHAL - sonda nemeri nic"; exit 1 }
$out = dotnet test tests/Gsd.IntegrationTests/Gsd.IntegrationTests.csproj -c Release --no-build --nologo --filter "FullyQualifiedName~CsrfCookieTests" 2>&1
$out | Select-String -Pattern 'Failed Gsd|Passed!|Failed!|Expected:|Actual:' | ForEach-Object { $_.Line }

cd W:\dev\gsd\repo
"=== generat slovniku: rezim -Check ==="
if (Test-Path scripts\generate-autorizacni-slovnik.ps1) {
  pwsh -NoProfile -File scripts\generate-autorizacni-slovnik.ps1 -Check 2>&1 | Select-Object -Last 15
  "EXIT=$LASTEXITCODE"
} else { Get-ChildItem scripts -Filter '*slovnik*' -Recurse | Select-Object FullName }
"=== sada brany ==="
pwsh -NoProfile -File tests\scripts\autorizacni_slovnik.tests.ps1 2>&1 | Select-String -Pattern 'FAIL|passed / ' | ForEach-Object { $_.Line }
"EXIT=$LASTEXITCODE"
"=== drift slovniku proti main ==="
git diff --stat -- docs/technical/autorizacni-slovnik.json
"(prazdne = 0 rozdilu)"

cd W:\dev\gsd\repo
foreach ($p in 5180,5373,5433) {
  $r = Test-NetConnection -ComputerName 127.0.0.1 -Port $p -InformationLevel Quiet -WarningAction SilentlyContinue
  "port {0,-5} obsazen: {1}" -f $p, $r
}
"=== .logs ==="
Get-ChildItem .logs -ErrorAction SilentlyContinue | Select-Object Name,Length,LastWriteTime | Format-Table -AutoSize
"=== PID soubory ==="
Get-ChildItem .logs -Filter '*.pid' -ErrorAction SilentlyContinue | ForEach-Object { "$($_.Name): $(Get-Content $_.FullName -Raw)" }

$org = 'https://dev.azure.com/wittenberger'; $proj = 'GSD'
$deadline = (Get-Date).AddMinutes(25)
do {
  Start-Sleep -Seconds 30
  $runs = az pipelines runs list --organization $org --project $proj --top 20 --query-order QueueTimeDesc --output json | ConvertFrom-Json
  $vetev = $runs | Where-Object { $_.sourceVersion -eq 'cab6d76eafb318643fe974a0c291892545aeb025' } | Sort-Object id -Descending | Select-Object -First 1
  $main  = $runs | Where-Object { $_.sourceVersion -eq 'aa96115' -or $_.sourceVersion -like 'aa96115*' } | Sort-Object id -Descending | Select-Object -First 1
} while ((Get-Date) -lt $deadline -and $vetev.status -ne 'completed')
"VETEV cab6d76: $($vetev.buildNumber) id=$($vetev.id) status=$($vetev.status) result=$($vetev.result) branch=$($vetev.sourceBranch)"
if ($main) { "MAIN  aa96115: $($main.buildNumber) id=$($main.id) status=$($main.status) result=$($main.result) branch=$($main.sourceBranch)" } else { "MAIN  aa96115: beh nenalezen ve 20 nejnovejsich" }
